package com.learnagent.memory;import com.learnagent.notification.*;import java.time.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.boot.context.event.ApplicationReadyEvent;import org.springframework.context.event.EventListener;import org.springframework.core.annotation.Order;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;@Component@ConditionalOnProperty(prefix="learnagent.memory-review",name="enabled",havingValue="true",matchIfMissing=true)public class MemoryReviewScheduler{private final MemoryReviewService reviews;private final NotificationService notifications;private final ZoneId zone;public MemoryReviewScheduler(MemoryReviewService reviews,NotificationService notifications,@Value("${learnagent.time-zone:Asia/Shanghai}")String zone){this.reviews=reviews;this.notifications=notifications;this.zone=ZoneId.of(zone);}@Scheduled(cron="${learnagent.memory-review.cron:0 0 8 * * *}",zone="${learnagent.time-zone:Asia/Shanghai}")public void scheduled(){notifyIfDue();}@EventListener(ApplicationReadyEvent.class)@Order(0)public void catchUp(){try{notifyIfDue();}catch(RuntimeException ignored){}}private void notifyIfDue(){int count=reviews.due(null).size();if(count==0)return;LocalDate date=LocalDate.now(zone);notifications.create(NotificationType.MEMORY_REVIEW,"今日记忆复习已就绪","按遗忘风险排序，共 "+count+" 张到期卡片，预计不超过15分钟。","/memory","MEMORY_REVIEW",null,"memory-review-"+date);}}
